var statsTab = e.target.closest('.tracker-tab[data-tab="stats"]');
// PATCH v1.0.11: программный клик (restoreTab при загрузке страницы) —
// НЕ открываем меню, а даём штатному обработчику просто восстановить вкладку.
if (statsTab && e.isTrusted === false) return;
if (statsTab) {
    e.preventDefault();

/* ============================================================
   PATCH v1.0.11 — МГНОВЕННЫЙ СПИННЕР НА ВСЕХ СОХРАНЕНИЯХ/СОЗДАНИЯХ
   Проблема: часть обработчиков (отметки, объединение задач, уведомления,
   статусы гипотез и др.) шлёт raw fetch() мимо apiJson — глобальный
   лоадер не показывается, при медленной сети (БД на сетевом диске)
   кажется, что кнопка «не сработала», пользователь жмёт повторно.
   Решение:
   1) обёртка window.fetch — ЛЮБОЙ не-GET запрос к /api/ включает
      #globalLoader на всё время запроса;
   2) capture-перехват pointerdown по кнопкам сохранения/создания
      в любой модалке — спиннер появляется МГНОВЕННО, ещё до старта
      fetch (если запрос не начался — авто-гашение через 3 с);
   3) страж от «застрявшего» лоадера (45 с) и поддержка suppress-флага
      удаления отметки (PATCH v1.0.14).
   ============================================================ */
(function(){
'use strict';
if (window.__trkGlobalSaveSpinnerV1011) return;
window.__trkGlobalSaveSpinnerV1011 = true;

var _net = 0;        // активные сетевые запросы (наши)
var _clk = 0;        // «мгновенные» показы по клику, ещё не подхваченные fetch
var _minTimer = null;
var _weActivated = false; // лоадер включили именно мы — только тогда мы его и гасим
var _firstStart = 0;

function _el(){ return document.getElementById('globalLoader'); }
function _setLabel(t){
    var l = _el(); if (!l) return;
    var x = l.querySelector('.gl-text'); if (x) x.textContent = t || 'Загрузка…';
}
function _render(){
    var l = _el(); if (!l) return;
    var want = (_net + _clk) > 0;
    if (window.__trkDelLogSuppressLoader) want = false; // v1.0.14: удаление отметки без двойного оверлея
    if (want) {
        if (_minTimer) { clearTimeout(_minTimer); _minTimer = null; }
        if (!l.classList.contains('active')) { _weActivated = true; _firstStart = Date.now(); }
        l.classList.add('active');
        _setLabel('Сохранение…');
    } else {
        if (_minTimer) return;
        _minTimer = setTimeout(function(){
            _minTimer = null;
            if ((_net + _clk) > 0) return;
            var el = _el(); if (!el) return;
            if (_weActivated) { el.classList.remove('active'); _weActivated = false; }
            _setLabel('');
        }, 300);
    }
}
/* если apiJson (свой счётчик) снял класс, пока наш запрос ещё летит — возвращаем */
function _installReassert(){
    var l = _el(); if (!l || l._spinnerReassertV1011) return;
    l._spinnerReassertV1011 = true;
    new MutationObserver(function(){
        if ((_net + _clk) > 0 && !window.__trkDelLogSuppressLoader && !l.classList.contains('active')) {
            l.classList.add('active');
        }
    }).observe(l, { attributes: true, attributeFilter: ['class'] });
}
/* страж: лоадер не должен висеть вечно при зависшем соединении */
setInterval(function(){
    if ((_net + _clk) > 0 && _firstStart && (Date.now() - _firstStart) > 45000) {
        _net = 0; _clk = 0; _render();
    }
}, 5000);

/* --- 1. Обёртка fetch: любой не-GET к /api/ -> лоадер на время запроса --- */
var _prevFetch = window.fetch;
if (typeof _prevFetch === 'function') {
    window.fetch = function(url, opts){
        var method = 'GET';
        try { method = String((opts && opts.method) || 'GET').toUpperCase(); } catch (e) {}
        var isApi = (typeof url === 'string' && url.indexOf('/api/') !== -1);
        if (!isApi || method === 'GET') {
            return _prevFetch.apply(this, arguments);
        }
        _net++;
        if (_clk > 0) _clk--;           // клик «подхвачен» реальным запросом
        _render();
        var p;
        try { p = _prevFetch.apply(this, arguments); }
        catch (e) { _net--; _render(); throw e; }
        return p.then(function(r){ _net--; _render(); return r; },
                      function(e){ _net--; _render(); throw e; });
    };
}

/* --- 2. Мгновенный спиннер по нажатию кнопки сохранения/создания в модалке --- */
var _SAVE_SEL = [
    '.modal.active .modal-actions button.btn-primary',
    '.modal.active button.btn-primary',
    '#saveTaskBtn', '#logSaveBtn', '#saveLogBtn',
    '.modal.active button[type="submit"]'
].join(', ');
document.addEventListener('pointerdown', function(e){
    if (!e.target || !e.target.closest) return;
    var btn = e.target.closest(_SAVE_SEL);
    if (!btn || btn.disabled) return;
    var txt = (btn.textContent || '');
    if (!/сохран|создат|добавит|применит|объединит|удалит|отправит|импорт/i.test(txt)) return;
    _clk++;
    _render();
    /* если обработчик не запустил fetch (валидация и т.п.) — гасим сами */
    setTimeout(function(){ if (_clk > 0) { _clk--; _render(); } }, 3000);
}, true);

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', _installReassert);
} else { _installReassert(); }
setTimeout(_installReassert, 500);
})();

/* ============================================================
   PATCH v1.0.11 — АВТООБНОВЛЕНИЕ БЕЗ F5 (синхронизация между пользователями)
   Проблема: задача, созданная/изменённая другим пользователем (например,
   админ назначил задачу сотруднику), не появлялась у сотрудника, пока
   тот не обновит страницу — состояние загружалось один раз при входе.
   Решение: лёгкий опрос /api/tracker/state каждые 30 с + при возврате
   фокуса/вкладки. Ответ сравнивается с текущим state по сигнатуре задач;
   полный refresh (trkRefreshAll) выполняется ТОЛЬКО при расхождении,
   и никогда — пока открыта модалка (чтобы не сбивать ввод).
   ============================================================ */
(function(){
'use strict';
if (window.__trkAutoSyncV1011) return;
window.__trkAutoSyncV1011 = true;

var POLL_MS = 30000;

function _sig(tasks){
    var s = '';
    (tasks || []).forEach(function(t){
        if (!t) return;
        s += (t.id || '') + '|' + (t.name || '') + '|' + (t.status || '') + '|'
           + (t.deadline || '') + '|' + (t.start_date || '') + '|'
           + ((t.assignees || []).join(',')) + '|' + (t.is_urgent ? 1 : 0)
           + '|' + (t.completed_at || '') + ';';
    });
    return s;
}

function _tick(){
    try {
        if (document.hidden) return;
        if (navigator && navigator.onLine === false) return;
        /* не дёргаем интерфейс, пока пользователь что-то вводит в модалке */
        if (document.querySelector('.modal.active')) return;
        fetch('/api/tracker/state', { credentials: 'same-origin', cache: 'no-store' })
            .then(function(r){ return r.ok ? r.json() : null; })
            .then(function(d){
                if (!d || !d.success) return;
                var serverSig = _sig(d.tasks);
                var clientSig = _sig((window.__trkState || {}).tasks);
                if (serverSig !== clientSig && typeof window.__trkRefreshAll === 'function') {
                    try { window.__trkRefreshAll(); } catch (e) {}
                }
            })
            .catch(function(){});
    } catch (e) {}
}

setInterval(_tick, POLL_MS);
window.addEventListener('focus', function(){ setTimeout(_tick, 300); });
document.addEventListener('visibilitychange', function(){
    if (!document.hidden) setTimeout(_tick, 300);
});
})();
